import { Group, PlaneGeometry, Mesh, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  // Destructure config
  const { position, rotation, scale, textContent, assets } = config;
  const group = new Group();

  // Plane with texture
  const texture = ctx.textureLoader.load(assets.imageUrl);
  const aspect = texture.image ? texture.image.width / texture.image.height : 1.6;
  const planeWidth = 1.5;
  const planeHeight = planeWidth / aspect;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ map: texture });
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Text overlay – headline “Features 1” (scene-unit height 0.34)
  const textMesh = createText(textContent.text, {
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 0.34,            // headline height in scene units
    align: 'center',
    anchor: { x: 0.5, y: 0.5 } // center
  });
  textMesh.position.z = 0.001; // slight offset to avoid z-fighting
  group.add(textMesh);

  // Apply scene placement
  group.position.set(position.x, position.y, position.z);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.set(scale.x, scale.y, scale.z);

  // Attach empty handler container
  group.userData.handlers = {};

  // Cleanup: dispose resources (no GSAP timelines to kill)
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
